# Homebrew formula that builds AgentManager from source (HEAD only).
#
# Most users want the prebuilt binary from the tap instead:
#   brew install kevinelliott/tap/agentmanager
# That formula is generated by GoReleaser on each release (see .goreleaser.yml)
# and lives in https://github.com/kevinelliott/homebrew-tap.
#
# To build the current main branch from this file:
#   brew install --HEAD --formula ./Formula/agentmanager.rb

class Agentmanager < Formula
  desc "CLI tool for managing AI development agents"
  homepage "https://kevinelliott.github.io/agentmanager/"
  license "MIT"
  head "https://github.com/kevinelliott/agentmanager.git", branch: "main"

  depends_on "go" => :build

  def install
    ldflags = %W[
      -s -w
      -X main.version=#{version}
      -X main.date=#{time.iso8601}
    ]

    system "go", "build", *std_go_args(ldflags:, output: bin/"agentmgr"), "./cmd/agentmgr"
    # The system tray helper needs cgo and desktop libraries; only macOS has
    # them without extra dependencies.
    if OS.mac?
      system "go", "build", *std_go_args(ldflags:, output: bin/"agentmgr-helper"), "./cmd/agentmgr-helper"
    end

    generate_completions_from_executable(bin/"agentmgr", "completion")
  end

  def caveats
    <<~EOS
      To start the background helper (systray):
        agentmgr helper start

    EOS
  end

  test do
    assert_match "AgentManager", shell_output("#{bin}/agentmgr version")
    assert_match "agentmgr", shell_output("#{bin}/agentmgr --help")
  end
end
